/**
 * Real-DuckDB proof of the annotated filter: the table of annotated rows a
 * sync builds, and the rows the filter keeps, counted and paged through
 * `buildRowQuery` as the grid pages them, against an oracle written in
 * JavaScript from the annotations themselves.
 *
 * The data is generated by formulas the oracle repeats, so the reference
 * order (NULLS LAST, `__rowid__` last) is computed without DuckDB. The
 * annotations mix row and cell scope with every severity, and add
 * column-scope annotations and rowIds no row has, which must keep nothing.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';

import { AnnotatedRowsTable } from '@/annotations/AnnotatedRowsTable';
import { AnnotationStore } from '@/annotations/AnnotationStore';
import type { AnnotationSeverity, NewAnnotation } from '@/annotations/types';
import { StateActions } from '@/core/Actions';
import { createTableState, initializeColumnsFromSchema } from '@/core/State';
import type { ColumnSchema, Filter, SortColumn } from '@/core/types';
import type { WorkerBridge } from '@/data/WorkerBridge';
import { filtersToWhereClause } from '@/filters/FilterSQL';
import { buildRowQuery } from '@/table/rowQuery';

import { createNodeDuckDB, type NodeDuckDBHarness } from '../helpers/duckdbNode';
import { makeNodeBridge } from '../helpers/nodeBridge';

const TOTAL_ROWS = 2_000;
const BLOCK = 128;
const SEVERITIES: AnnotationSeverity[] = ['error', 'warning', 'info'];
const BIT: Record<AnnotationSeverity, number> = { error: 1, warning: 2, info: 4 };

/** A row of `base`, as the SQL below makes it. */
interface Row {
  __rowid__: number;
  grp: number;
  val: number | null;
  label: string | null;
}

function rowOf(i: number): Row {
  return {
    __rowid__: i,
    grp: i % 7,
    val: i % 11 === 0 ? null : (i * 7919) % 1000,
    label: i % 13 === 0 ? null : `r${(i * 104729) % 5000}`,
  };
}

const BASE_SQL = (name: string, rows: number) => `CREATE TABLE "${name}" AS
  SELECT CAST(range AS BIGINT) AS "__rowid__",
         CAST(range % 7 AS INTEGER) AS grp,
         CASE WHEN range % 11 = 0 THEN NULL ELSE CAST((range * 7919) % 1000 AS INTEGER) END AS val,
         CASE WHEN range % 13 = 0 THEN NULL ELSE 'r' || ((range * 104729) % 5000) END AS label
  FROM range(${rows})`;

const SCHEMA: ColumnSchema[] = [
  { name: '__rowid__', type: 'integer', nullable: false, originalType: 'BIGINT', system: true },
  { name: 'grp', type: 'integer', nullable: false, originalType: 'INTEGER' },
  { name: 'val', type: 'integer', nullable: true, originalType: 'INTEGER' },
  { name: 'label', type: 'string', nullable: true, originalType: 'VARCHAR' },
];

/** Row and cell annotations over `rows` rows, and some that single out no row. */
function annotationsFor(rows: number): NewAnnotation[] {
  const out: NewAnnotation[] = [];
  for (let i = 0; i < rows; i++) {
    if (i % 5 === 0) {
      out.push({ scope: 'row', rowId: i, severity: SEVERITIES[i % 3]!, message: 'row' });
    }
    if (i % 7 === 3) {
      out.push({
        scope: 'cell',
        rowId: i,
        column: i % 2 ? 'val' : 'label',
        severity: SEVERITIES[(i >> 1) % 3]!,
        message: 'cell',
      });
    }
    if (i % 35 === 3) {
      // A second annotation on the same cell.
      out.push({ scope: 'cell', rowId: i, column: 'val', severity: 'info', message: 'again' });
    }
  }
  out.push({ scope: 'column', column: 'val', severity: 'error', message: 'whole column' });
  for (const rowId of [-1, 2.5, 1e20, rows + 5]) {
    out.push({ scope: 'row', rowId, severity: 'error', message: 'no such row' });
  }
  return out;
}

/** The oracle: each row's severity bits, from the annotations themselves. */
function masksOf(annotations: NewAnnotation[]): Map<number, number> {
  const masks = new Map<number, number>();
  for (const ann of annotations) {
    if (ann.scope === 'column') continue;
    masks.set(ann.rowId, (masks.get(ann.rowId) ?? 0) | BIT[ann.severity]);
  }
  return masks;
}

/** NULLS LAST, as the grid orders; `__rowid__` last, unless sorted on. */
function compareRows(a: Row, b: Row, sort: SortColumn[]): number {
  for (const { column, direction } of sort) {
    const x = a[column as keyof Row];
    const y = b[column as keyof Row];
    if (x === y) continue;
    if (x === null) return 1;
    if (y === null) return -1;
    const order = x < y ? -1 : 1;
    return direction === 'asc' ? order : -order;
  }
  if (sort.some((s) => s.column === '__rowid__')) return 0;
  return a.__rowid__ - b.__rowid__;
}

/** A bridge over the Node connection, with the cache the sync clears. */
function bridgeOver(harness: NodeDuckDBHarness): WorkerBridge {
  const node = makeNodeBridge(harness.conn);
  return {
    query: node.query.bind(node),
    clearQueryCache: () => undefined,
  } as unknown as WorkerBridge;
}

/** A table's state, actions and annotation store, and its table of annotated rows. */
function tableOf(bridge: WorkerBridge, name: string, annotations: NewAnnotation[]) {
  const state = createTableState();
  state.tableName.set(name);
  state.baseTableName.set(name);
  initializeColumnsFromSchema(state, SCHEMA);
  const actions = new StateActions(state, bridge);
  const store = new AnnotationStore();
  if (annotations.length > 0) store.addMany(annotations);
  const rows = new AnnotatedRowsTable({ state, actions, bridge, store });
  return { state, actions, store, rows };
}

describe('the annotated filter on real DuckDB', () => {
  let harness: NodeDuckDBHarness;
  let bridge: WorkerBridge;
  const annotations = annotationsFor(TOTAL_ROWS);
  const masks = masksOf(annotations);
  const data = Array.from({ length: TOTAL_ROWS }, (_, i) => rowOf(i));
  let base: ReturnType<typeof tableOf>;

  beforeAll(async () => {
    harness = await createNodeDuckDB();
    bridge = bridgeOver(harness);
    await harness.conn.query(BASE_SQL('base', TOTAL_ROWS));
    // A derived-column view, as DerivedColumnManager builds one: it keeps
    // `__rowid__`.
    await harness.conn.query(
      `CREATE VIEW "__dt_view_base__" AS SELECT *, (val * 2) AS dbl FROM "base"`,
    );
    base = tableOf(bridge, 'base', annotations);
    await expect(base.rows.ensureFresh()).resolves.toBe('__dt_annot_base__');
  }, 30_000);

  afterAll(async () => {
    base?.rows.destroy();
    await harness?.cleanup();
  });

  it('holds each annotated row once, with its severity bits, typed as the contract says', async () => {
    const rows = await bridge.query<{ __rowid__: number; __mask__: number }>(
      'SELECT "__rowid__", "__mask__" FROM "__dt_annot_base__" ORDER BY 1',
    );
    const expected = [...masks]
      .filter(([rowId]) => Number.isInteger(rowId) && rowId >= 0 && rowId < 2 ** 50)
      .sort(([a], [b]) => a - b)
      .map(([rowId, mask]) => ({ __rowid__: rowId, __mask__: mask }));
    expect(rows).toEqual(expected);
    const types = await bridge.query<{ column_name: string; column_type: string }>(
      'SELECT column_name, column_type FROM (DESCRIBE "__dt_annot_base__")',
    );
    expect(types).toEqual([
      { column_name: '__rowid__', column_type: 'BIGINT' },
      { column_name: '__mask__', column_type: 'UTINYINT' },
    ]);
  });

  const annotated = (severities?: AnnotationSeverity[]): Filter => ({
    type: 'annotated',
    column: '__annotated__',
    ...(severities ? { severities } : {}),
    table: 'base',
  });

  interface Case {
    label: string;
    relation: string;
    filters: Filter[];
    sort: SortColumn[];
    keep: (row: Row) => boolean;
  }

  const kept = (bits: number) => (row: Row) => ((masks.get(row.__rowid__) ?? 0) & bits) !== 0;
  const CASES: Case[] = [
    { label: 'any severity', relation: 'base', filters: [annotated()], sort: [], keep: kept(7) },
    {
      label: 'errors only, sorted on a column with ties and NULLs',
      relation: 'base',
      filters: [annotated(['error'])],
      sort: [{ column: 'val', direction: 'asc' }],
      keep: kept(1),
    },
    {
      label: 'warnings and infos, sorted descending on text',
      relation: 'base',
      filters: [annotated(['warning', 'info'])],
      sort: [{ column: 'label', direction: 'desc' }],
      keep: kept(6),
    },
    {
      label: 'with a range filter, multi-column sort',
      relation: 'base',
      filters: [annotated(), { type: 'range', column: 'val', min: 200, max: 700 }],
      sort: [
        { column: 'grp', direction: 'asc' },
        { column: 'val', direction: 'desc' },
      ],
      keep: (row) => kept(7)(row) && row.val !== null && row.val >= 200 && row.val < 700,
    },
    {
      label: 'with a set filter, sorted descending on __rowid__',
      relation: 'base',
      filters: [{ type: 'set', column: 'grp', values: [1, 3, 6] }, annotated(['info', 'error'])],
      sort: [{ column: '__rowid__', direction: 'desc' }],
      keep: (row) => kept(5)(row) && [1, 3, 6].includes(row.grp),
    },
    {
      label: 'on the derived-column view, sorted by its expression',
      relation: '__dt_view_base__',
      filters: [annotated(['error', 'warning'])],
      sort: [{ column: 'dbl', direction: 'desc' }],
      keep: kept(3),
    },
  ];

  for (const c of CASES) {
    it(`counts and pages the annotated view: ${c.label}`, async () => {
      const sortKey = c.sort.map((s) => (s.column === 'dbl' ? { ...s, column: 'val' } : s));
      const reference = data
        .filter(c.keep)
        .sort((a, b) => compareRows(a, b, sortKey))
        .map((row) => row.__rowid__);
      expect(reference.length).toBeGreaterThan(BLOCK);

      const [{ cnt }] = await bridge.query<{ cnt: number }>(
        `SELECT COUNT(*) AS cnt FROM "${c.relation}" WHERE ${filtersToWhereClause(c.filters)}`,
      );
      expect(Number(cnt)).toBe(reference.length);

      const paged: number[] = [];
      for (let offset = 0; offset < reference.length; offset += BLOCK) {
        const rows = await bridge.query<{ __rowid__: number }>(
          buildRowQuery({
            tableName: c.relation,
            columns: ['grp', 'val', 'label'],
            sortColumns: c.sort,
            filters: c.filters,
            offset,
            limit: BLOCK,
            schema: SCHEMA,
            rowidFastPath: false,
          }),
        );
        paged.push(...rows.map((row) => row.__rowid__));
      }
      expect(paged).toEqual(reference);
    });
  }

  it('follows the annotations once synced again: a removal, a clear', async () => {
    await harness.conn.query(BASE_SQL('live', 100));
    const live = tableOf(bridge, 'live', []);
    const count = async (severities?: AnnotationSeverity[]) => {
      const filters: Filter[] = [{ ...annotated(severities), table: 'live' }];
      const [{ cnt }] = await bridge.query<{ cnt: number }>(
        `SELECT COUNT(*) AS cnt FROM "live" WHERE ${filtersToWhereClause(filters)}`,
      );
      return Number(cnt);
    };
    const [first] = live.store.addMany([
      { scope: 'row', rowId: 10, severity: 'error', message: 'a' },
      { scope: 'cell', rowId: 20, column: 'val', severity: 'warning', message: 'b' },
    ]);
    await live.rows.ensureFresh();
    expect(await count()).toBe(2);
    live.store.remove(first!.id);
    await live.rows.ensureFresh();
    expect(await count()).toBe(1);
    expect(await count(['error'])).toBe(0);
    live.store.clear('all');
    await live.rows.ensureFresh();
    expect(await count()).toBe(0);
    live.rows.destroy();
  });
});

describe('syncs on real DuckDB', () => {
  let harness: NodeDuckDBHarness;
  let bridge: WorkerBridge;

  beforeAll(async () => {
    harness = await createNodeDuckDB();
    bridge = bridgeOver(harness);
  }, 30_000);

  afterAll(async () => {
    await harness?.cleanup();
  });

  const read = (table: string) =>
    bridge.query<{ __rowid__: number; __mask__: number }>(
      `SELECT "__rowid__", "__mask__" FROM "${table}" ORDER BY 1`,
    );

  it('of no annotated rows: an empty table of the contract’s columns', async () => {
    const { rows } = tableOf(bridge, 'empty', [
      { scope: 'column', column: 'val', severity: 'error', message: 'only a column' },
    ]);
    await expect(rows.ensureFresh()).resolves.toBe('__dt_annot_empty__');
    await expect(read('__dt_annot_empty__')).resolves.toEqual([]);
    rows.destroy();
  });

  it('of one annotated row', async () => {
    const { rows } = tableOf(bridge, 'one', [
      { scope: 'cell', rowId: 41, column: 'val', severity: 'warning', message: 'w' },
    ]);
    await rows.ensureFresh();
    await expect(read('__dt_annot_one__')).resolves.toEqual([{ __rowid__: 41, __mask__: 2 }]);
    rows.destroy();
  });

  it('of 10,000 annotated rows, across chunks, rowIds past 2^32 included', async () => {
    const annotations: NewAnnotation[] = Array.from({ length: 10_000 }, (_, i) => ({
      scope: 'row',
      rowId: i < 9_990 ? i * 3 : 2 ** 40 + i,
      severity: SEVERITIES[i % 3]!,
      message: 'r',
    }));
    const state = createTableState();
    state.tableName.set('many');
    state.baseTableName.set('many');
    const actions = new StateActions(state, bridge);
    const store = new AnnotationStore();
    store.addMany(annotations);
    const rows = new AnnotatedRowsTable({ state, actions, bridge, store, chunkSize: 1_000 });
    await rows.ensureFresh();
    const synced = await read('__dt_annot_many__');
    expect(synced).toHaveLength(10_000);
    expect(synced).toEqual(
      annotations.map((ann, i) => ({
        __rowid__: (ann as { rowId: number }).rowId,
        __mask__: BIT[SEVERITIES[i % 3]!],
      })),
    );
    rows.destroy();
  });

  it('goes with the statement WorkerBridge.dropTable sends, as the facade drops it with its base table', async () => {
    const { rows } = tableOf(bridge, 'dropped', [
      { scope: 'row', rowId: 5, severity: 'error', message: 'e' },
    ]);
    await rows.ensureFresh();
    rows.destroy();
    await expect(read('__dt_annot_dropped__')).resolves.toEqual([{ __rowid__: 5, __mask__: 1 }]);
    // A temporary table, found by its name alone as the base table is.
    await bridge.query('DROP TABLE IF EXISTS "__dt_annot_dropped__"');
    await expect(read('__dt_annot_dropped__')).rejects.toThrow(/does not exist/);
  });

  it('two tables on one database keep two tables of annotated rows', async () => {
    await harness.conn.query(BASE_SQL('left', 50));
    await harness.conn.query(BASE_SQL('right', 50));
    const left = tableOf(bridge, 'left', [
      { scope: 'row', rowId: 1, severity: 'error', message: 'l' },
      { scope: 'row', rowId: 2, severity: 'error', message: 'l' },
    ]);
    const right = tableOf(bridge, 'right', [
      { scope: 'row', rowId: 3, severity: 'info', message: 'r' },
    ]);
    await Promise.all([left.rows.ensureFresh(), right.rows.ensureFresh()]);
    const count = async (relation: string) => {
      const filters: Filter[] = [{ type: 'annotated', column: '__annotated__', table: relation }];
      const [{ cnt }] = await bridge.query<{ cnt: number }>(
        `SELECT COUNT(*) AS cnt FROM "${relation}" WHERE ${filtersToWhereClause(filters)}`,
      );
      return Number(cnt);
    };
    expect(await count('left')).toBe(2);
    expect(await count('right')).toBe(1);
    await expect(read('__dt_annot_left__')).resolves.toEqual([
      { __rowid__: 1, __mask__: 1 },
      { __rowid__: 2, __mask__: 1 },
    ]);
    left.rows.destroy();
    right.rows.destroy();
  });
});
